"""Committed open episodes must be regenerated byte-for-byte from (seed, config, version)."""

import json
import os

import pytest

from auditenv import canon
from auditenv.books import books_files
from auditenv.cli import ROOT, split_episodes
from auditenv.generator import generate_episode
from auditenv.version import GENERATOR_VERSION

INDEX = os.path.join(ROOT, "episodes", "index.json")


def _index():
    with open(INDEX, encoding="utf-8") as fh:
        return json.load(fh)


@pytest.mark.skipif(not os.path.exists(INDEX), reason="run `python -m auditenv generate` first")
def test_committed_episodes_regenerate_exactly():
    index = _index()
    assert index["generator_version"] == GENERATOR_VERSION
    expected = {(e["split"], e["seed"]): e for e in index["episodes"]}
    for split in ("train", "dev"):
        for seed, cfg in split_episodes(split):
            ep = generate_episode(seed, cfg)
            entry = expected[(split, seed)]
            assert canon.hash_obj(books_files(ep.public)) == entry["books_sha256"]
            assert canon.hash_obj(ep.truth) == entry["truth_sha256"]
            on_disk = os.path.join(ROOT, "episodes", split, f"seed_{seed}", "books")
            for name, text in books_files(ep.public).items():
                with open(os.path.join(on_disk, name), encoding="utf-8", newline="") as fh:
                    assert fh.read() == text, (split, seed, name)
